{
  "name": "沃特洛PID温度控制器",
  "name_en": "Watlow PID Temperature Controller",
  "manufacturer": "Watlow",
  "description": "用于实验室温度调节的PID温度控制器。该设备通过串口使用 BACnet TP/MS 通信，可读取当前温度、读取或修改温度设定值，并访问控制器参数，以实现加热过程或热工系统的闭环控制。",
  "description_en": "A PID temperature controller used for laboratory temperature regulation. It communicates over serial using BACnet TP/MS and supports reading the current temperature, reading or changing the temperature setpoint, and accessing controller parameters for closed-loop control of heating or thermal processes.",
  "actions": [
    {
      "action_name": "auto-open",
      "description": "打开与温度控制器的串口通信连接。",
      "description_en": "Open the serial communication connection to the temperature controller."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与温度控制器的串口通信连接。",
      "description_en": "Close the serial communication connection to the temperature controller."
    },
    {
      "action_name": "auto-read",
      "description": "读取控制器当前测得的温度值。",
      "description_en": "Read the current measured temperature from the controller."
    },
    {
      "action_name": "auto-readSetpoint",
      "description": "读取控制器当前的温度设定值。",
      "description_en": "Read the current temperature setpoint from the controller."
    },
    {
      "action_name": "auto-readParam",
      "description": "按参数 ID 读取控制器参数值。",
      "description_en": "Read a controller parameter value by parameter ID."
    },
    {
      "action_name": "auto-write",
      "description": "写入新的温度设定值到控制器。",
      "description_en": "Write a new temperature setpoint to the controller."
    },
    {
      "action_name": "auto-writeParam",
      "description": "按参数 ID 写入控制器参数值。",
      "description_en": "Write a controller parameter value by parameter ID."
    }
  ],
  "tag_hints": [
    "PID temperature control",
    "temperature setpoint control",
    "BACnet TP/MS",
    "serial communication",
    "thermal process control",
    "heating control"
  ]
}

